export async function loadHelpArticles() {
  try {
    const resp = await fetch('/help-articles.json');
    if (!resp.ok) return null;
    const json = await resp.json();
    return (json.data || [])
      .filter((r) => r.title && r.text)
      .map((r, i) => ({ id: r.id || `d${i + 1}`, sec: r.section || 'Help', title: r.title, text: r.text }));
  } catch (e) {
    return null;
  }
}

