function samHistory(){
  const stress=[2,4,3,5,2,1,4,3,2,5,4],hi=[138,141,139,140,137],lo=[124,126,125,123,127,125];
  let h=0,l=0;const r=[];
  stress.forEach((s,i)=>{const day=i+1,sys=s>=4?hi[h++]:lo[l++];
    r.push({day,type:'bp',sys,dia:Math.round(sys*.62),stress:s});
    r.push({day,type:'glucose',value:112+((i*17)%34)});
    r.push({day,type:'glucose',value:118+((i*23)%30)});});
  return r;
}
