function stem(w){return w.length>4?w.replace(/(ing|ed|es|s)$/,''):w;}
function tok(s){return String(s).toLowerCase().replace(/[^a-z0-9 ]/g,' ').split(/\s+/).filter(w=>w.length>1&&!STOP.has(w)).map(w=>{const st=stem(w);return SYN[w]||SYN[st]||st;});}
const IDX=(()=>{const docs=DOCS.map(d=>{const t=tok(d.title+' '+d.title+' '+d.text);const tf={};t.forEach(w=>tf[w]=(tf[w]||0)+1);return {d,tf,len:t.length};});
  const df={};docs.forEach(x=>Object.keys(x.tf).forEach(w=>df[w]=(df[w]||0)+1));
  return {docs,df,avg:docs.reduce((s,x)=>s+x.len,0)/docs.length,N:docs.length};})();
function retrieve(q,k=3){
  const qt=[...new Set(tok(q))],k1=1.4,b=.75;
  const scored=IDX.docs.map(x=>{let s=0;qt.forEach(w=>{const f=x.tf[w];if(!f)return;const idf=Math.log(1+(IDX.N-IDX.df[w]+.5)/(IDX.df[w]+.5));s+=idf*f*(k1+1)/(f+k1*(1-b+b*x.len/IDX.avg));});return {doc:x.d,score:+s.toFixed(2)};}).filter(r=>r.score>0).sort((a,b)=>b.score-a.score);
  const top=scored[0]?scored[0].score:0;
  return {hits:scored.filter(r=>r.score>=Math.max(1.2,top*.6)).slice(0,k),terms:qt};
}
function personalLine(q){
  const t=tok(q),c=myCombo(),o=openOrder(),upd=updFor();
  if(t.includes('update')&&upd)return verified(upd)?`For you: ${upd.os} is verified for your ${c.phone}, so it is safe to update.`:`For you: ${upd.os} is out for your ${c.phone} but not verified yet (stage: ${STAGES[upd.stage]}). Wait to update so your meter keeps working.`;
  if(t.some(w=>['phone','software','update','verified','meter','error'].includes(w)))return verified(c)?`For you: your ${c.phone} on ${c.os} is verified, so your meter should work.`:`For you: your ${c.phone} on ${c.os} isn't verified yet (stage: ${STAGES[c.stage]}). Use one of the options in Device meanwhile.`;
  if(t.some(w=>['strip','delivery','order'].includes(w)))return `For you: ${S.strips} strips left (about ${daysLeft()} days). ${o?'Your box arrives day '+o.arrive+'.':'Next box ships at '+RP()+' strips.'}`;
  if(t.some(w=>['plan','billing','cancel'].includes(w)))return S.pay==='plan'?'For you: your employer plan pays, so there is nothing to cancel or pay.':'For you: you pay $33 a month. Pause or cancel is in Supplies › My plan.';
  return '';
}
function helpAnswer(q){
  const r=retrieve(q);
  if(!r.hits.length)return {text:"I couldn't find this in the help library, and I don't want to guess. I've passed your question to a person on the support team. They'll reply here.",handover:true,sources:[],terms:r.terms};
  const main=r.hits[0].doc,sents=main.text.match(/[^.!?]+[.!?]/g)||[main.text];
  let text=sents.slice(0,3).map(s=>s.trim()).join(' ')+' [1]';
  if(r.hits[1]&&r.hits[1].score>r.hits[0].score*.7)text+=`\n\nAlso relevant: ${r.hits[1].doc.title} [2].`;
  const p=personalLine(q);if(p)text+='\n\n'+p;
  return {text,handover:false,sources:r.hits.map(h=>({id:h.doc.id,title:h.doc.title,score:h.score})),terms:r.terms};
}

/* ---------- DocIQ (demo AI: rules that imitate the model) ---------- */
const REASONS={
 strips:{label:'Out of strips',btn:'Reorder strips'},
 phone:{label:'Phone or app not working with the meter',btn:'Check my phone'},
 meter:{label:'Meter problem',btn:'Fix my meter'},
 busy:{label:'Busy or forgot',btn:'Set a gentle reminder'},
 fewer:{label:'Too many reminders',btn:'Choose fewer reminders'},
 low:{label:'Feeling low or stressed',btn:'Talk to someone'},
 other:{label:'Something else',btn:'Message my coach'}
};
function classify(text){
  const t=text.toLowerCase();let r='other';
  if(/strip|run out|ran out|out of/.test(t))r='strips';
  else if(/phone|update|ios|android|compatib|app (won|does|is)|crash/.test(t))r='phone';
  else if(/meter|error|broken|not working|doesn.t work|plug|connect/.test(t))r='meter';
  else if(/remind|notif|annoy|too many|spam/.test(t))r='fewer';
  else if(/low|sad|down|stress|anxious|overwhelm|tired of/.test(t))r='low';
  else if(/busy|forgot|travel|holiday|time|work/.test(t))r='busy';
  const replies={strips:"Thanks for telling us. Running out shouldn't stop you, so let's get strips on the way now.",phone:"Thanks, that helps. It sounds like your phone and meter aren't working together. Let's check your phone and find a way to keep recording.",meter:"Sorry about that. Let's go through a few quick fixes, and we'll replace the meter if they don't work.",busy:"That's completely normal. Would one gentle reminder at a time that suits you help?",fewer:"Got it, fewer reminders. You choose the number and we'll only send the most useful ones.",low:"Thank you for telling us. That matters more than any reading. Would you like to talk to your coach?",other:"Thanks for sharing. Your coach can help you work out what would make this easier."};
  return {reason:r,reply:replies[r]};
}
function stats(){
  const bp=S.readings.filter(r=>r.type==='bp'&&r.day>S.day-14),wS=bp.filter(r=>r.stress!=null);
  const hi=wS.filter(r=>r.stress>=4),lo=wS.filter(r=>r.stress<4);
  const avg=(a,k='sys')=>a.length?Math.round(a.reduce((s,r)=>s+r[k],0)/a.length):0;
  const gl=S.readings.filter(r=>r.type==='glucose'&&r.day>S.day-14);
  return {days:wS.length,hi:avg(hi),lo:avg(lo),nHi:hi.length,nLo:lo.length,sys:avg(bp),dia:avg(bp,'dia'),bpN:bp.length,
    glN:gl.length,glAvg:gl.length?Math.round(gl.reduce((s,r)=>s+r.value,0)/gl.length):0,inRange:gl.filter(r=>r.value>=70&&r.value<=180).length,
    glDays:new Set(gl.map(r=>r.day)).size,stressAvg:wS.length?(wS.reduce((s,r)=>s+r.stress,0)/wS.length).toFixed(1):'–',
    bpList:bp.slice(-14),glList:gl.slice(-14).map(r=>r.value),sysList:bp.slice(-14).map(r=>r.sys),stList:wS.slice(-14).map(r=>r.stress)};
}
function healthAnswer(key){
  const st=stats();
  if(key==='bp'){
    if(!has('bp'))return {tag:'Advisor',t:'Blood pressure isn\'t one of your programs yet, so I have no readings to look at.',a:[]};
    if(st.days<10||!st.nHi||!st.nLo)return {tag:'Advisor · from your readings',t:`I look for patterns once there are 10 days with both a blood pressure reading and a stress check. You have ${st.days} so far.${st.bpN?` Your 14-day average is ${st.sys}/${st.dia}.`:''}`,a:[['nav:insights','Open Insights']]};
    return {tag:'Advisor · from your readings',t:`On the ${st.nHi} days you rated stress 4 or 5, your systolic blood pressure averaged ${st.hi}. On the other ${st.nLo} days it averaged ${st.lo}. That's a pattern in your own data, not a diagnosis, and stress may not be the cause.`,a:[['breathe','Try 2-minute breathing'],['shareCoach','Share with my coach']]};
  }
  if(key==='glp')return {tag:'Advisor · GLP-1 companion',t:'Nausea is common in the first weeks or after a dose increase. Smaller meals, eating slowly and sipping water often help. I have logged it for your care team. If you vomit repeatedly, cannot keep fluids down or have severe stomach pain, contact a provider today.',a:[['logged','Logged: nausea'],['provider','Talk to a provider']]};
  if(key==='skip'){
    const g=st.glN?` ${st.inRange} of your last ${st.glN} glucose readings were in the 70 to 180 mg/dL range.`:'';
    return {tag:'Sentinel',t:`One missed day is fine.${g} Want me to move today's reminder to 7 pm instead?`,a:[['move7','Move to 7 pm'],['keep','Keep it']]};
  }
  if(key==='food')return {tag:'Advisor · from your meal tags',t:'In your sample meal tags, glucose rose most after white rice and juice. Before a walk, a small snack with protein, like yogurt or a handful of nuts, usually keeps you steadier. Your coach can build a full meal plan with you.',a:[['shareCoach','Ask my coach'],['remind','Remind me after lunch']]};
  return null;
}
const SUGG=[['Why is my BP higher this week?','bp'],['Should I update my phone?','glu'],['When do my strips arrive?','glu'],['I feel sick after my GLP-1 shot','glp'],['Can I skip today\'s reading?',null],['How do I cancel?',null],['Can my daughter see my readings?',null]];
function askDoc(q){
  S.chat.push({who:'me',t:q});
  if(CRISIS.test(q)){S.chat.push({who:'sys',t:'Support options shown. If you are in danger, call or text 988, or call 911.'});log('rule','Crisis words in DocIQ chat: support screen shown, text not sent to AI.');U.sheet='crisis';render();return;}
  U.thinking=true;render();
  setTimeout(()=>{
    U.thinking=false;
    const low=q.toLowerCase();let key=null;
    if(/(^|\W)bp(\W|$)|blood pressure/.test(low))key='bp';
    else if(/glp|shot|nause|sick|ozempic|wegovy|injection/.test(low))key='glp';
    else if(/skip|miss/.test(low)&&/read|test|check/.test(low))key='skip';
    else if(/\beat\b|food|snack|meal|diet/.test(low))key='food';
    const h=key&&healthAnswer(key);
    if(h){S.chat.push({who:'ai',tag:h.tag,t:h.t,a:h.a,doneA:{}});log('ai',`DocIQ answered a health question from Sam's own readings (${key}).`);}
    else{
      const r=helpAnswer(q);
      S.chat.push({who:'ai',tag:'Helper · from the help library',t:r.text,sources:r.sources,terms:r.terms});
      if(r.handover){S.chat.push({who:'sys',t:'Handed to a person on the support team. They reply here.'});log('ai','DocIQ found no matching help article, so the question went to a person.');}
      else log('ai',`DocIQ answered from ${r.sources.length} help article(s), with sources.`);
    }
    render();
  },550);
}
function coachSummary(){
  const st=stats(),o=openOrder(),c=myCombo();
  return `Weekly summary from ${S.name} (shared by the member)\n• Blood pressure on ${st.bpN} of the last 14 days${st.days>=10?`; ${st.hi} on high-stress days vs ${st.lo} on calmer days`:''}.\n• Glucose readings: ${st.glN} (${st.inRange} in 70–180 range).\n• Strips: ${S.strips} left; ${o?'box arrives day '+o.arrive:'no order open'}.\n• Phone: ${c.phone} on ${c.os} (${verified(c)?'verified':'not verified yet'}).${S.exp>=4?'\n• Breathing experiment: 10 points lower after breathing.':''}`;
}

/* ---------- simulation ---------- */
function takeGlucose(silent){
  if(!has('glu'))return false;
  const c=myCombo();
  if(!verified(c)){
    S.blocked=`Meter reading not recorded: ${c.phone} on ${c.os} isn't verified yet.`;c.errors+=1;
    if(!silent){log('rule',`Reading blocked: ${c.phone} · ${c.os} is not verified. Member shown ways to keep recording.`);S.scr='device';toast("This phone isn't verified with your meter yet");}
    return false;
  }
  if(S.strips<=0){if(!silent)toast('No strips left. Reorder in Supplies.');return false;}
  const v=105+Math.round(rand()*45);
  S.strips-=1;S.today.glucose+=1;S.lastGlucose=S.day;
  S.readings.push({day:S.day,type:'glucose',value:v});
  checkReorder();
  return v;
}
function logBp(){
  if(!has('bp')||S.readings.some(r=>r.day===S.day&&r.type==='bp'))return;
  const s=S.today.stress??(has('mind')?1+Math.floor(rand()*5):null);
  const sys=s!=null&&s>=4?136+Math.round(rand()*6):122+Math.round(rand()*6);
  S.readings.push({day:S.day,type:'bp',sys,dia:Math.round(sys*.62),stress:s});
  S.today.bp=true;
}
function placeOrder(manual){
  if(openOrder())return null;
  const late=daysLeft()<S.lead,lead=late?S.expressLead:S.lead;
  const o={id:S.nextOrder++,made:S.day,arrive:S.day+lead,qty:50,speed:late?'express':'standard',status:'On the way'};
  S.orders.unshift(o);
  log('rule',`${manual?'Manual':'Automatic'} order #${o.id}: ${S.strips} strips left${manual?'':' (at or below the reorder point of '+RP()+')'}. `+(late?`Standard (${S.lead} days) would arrive after run-out, so it ships express (${S.expressLead} days) at no extra cost.`:`Standard delivery, arrives day ${o.arrive}.`));
  return o;
}
function checkReorder(){if(has('glu')&&S.auto&&S.strips<=RP()&&!openOrder()){const o=placeOrder(false);if(o)U.pending=`Box of 50 strips on the way · arrives day ${o.arrive}`;}}
function advance(n){
  for(let i=0;i<n;i++){
    if(S.recording){logBp();while(S.today.glucose<S.use){if(!takeGlucose(true))break;}if(has('mind')&&S.today.stress==null){const r=S.readings.find(x=>x.day===S.day&&x.type==='bp');if(r&&r.stress==null)r.stress=1+Math.floor(rand()*5);}}
    if(S.blocked&&S.recording){S.reports.push({day:S.day,combo:S.combo,text:'Automatic: meter reading failed'});log('rule',`Automatic error report sent for ${myCombo().phone} · ${myCombo().os}.`);}
    S.day+=1;S.today={bp:false,glucose:0,glp:false,move:false,stress:null,breath:false};S.blocked=null;S.bpHigh=false;
    S.orders.forEach(o=>{if(o.status!=='Delivered'&&S.day>=o.arrive){o.early=S.strips>0;o.status='Delivered';S.strips+=o.qty;log('rule',`Order #${o.id} delivered: +${o.qty} strips (now ${S.strips})${o.early?', before run-out':', after run-out'}.`);}});
    S.combos.forEach(c=>{
      if(c.release!=null&&S.day>=c.release&&c.expected>0){const mv=Math.min(c.expected,160);c.expected-=mv;c.members+=mv;if(c.from){const f=combo(c.from);f.members=Math.max(0,f.members-mv);}if(!verified(c))c.errors+=Math.round(mv*.12);}
      if(!verified(c)&&c.members>0)c.errors+=Math.round(c.members/400);
    });
    S.combos.forEach(c=>{
      if(c.stage===0&&c.release!=null&&S.day>=c.release-2){setStage(c.id,1);c.since=S.day;}
      else if(c.stage>0&&c.stage<4&&S.day-(c.since??0)>=2){setStage(c.id,c.stage+1);c.since=S.day;}
    });
    checkReorder();
    if(has('glu')){
      const gap=S.day-S.lastGlucose;
      if(gap>=3&&!S.checkin.due&&!S.checkin.answered){S.checkin={due:true,answered:false,result:null};log('rule',`No glucose reading for ${gap} days, so Today asks ${S.name} why (instead of more reminders).`);}
      if(gap<3&&S.checkin.answered)S.checkin={due:false,answered:false,result:null};
    }
  }
  if(U.pending){const p=U.pending;U.pending=null;toast(`Day ${S.day} · ${p}`);}else toast('Day '+S.day);
}
function setStage(id,st){
  const c=combo(id),was=c.stage;c.stage=Math.max(0,Math.min(4,st));if(c.stage===was)return;
  log('team',`${c.phone} · ${c.os}: ${STAGES[was]} → ${STAGES[c.stage]}${c.stage===4?' (signed off by a person)':''}.`);
  if(c.stage===4){
    log('rule',`Members on ${c.phone} · ${c.os} told it's now verified (${c.members.toLocaleString('en-US')} members unblocked).`);
    if(S.combo===id)S.notified[id]='verified';
    else if(c.isUpdate&&S.combo===c.from){S.notified[id]='safe';S.osDismissed=false;}
  }
}

